from hermes_tools import terminal
cmd="python3 -c 'import json; g=[[0]*22 for _ in range(23)];
# Preserve source frame (color 7), with its exemplar interior.
for r in range(12,17):
 for c in range(1,9):
  if r in (12,16) or c in (1,8): g[r][c]=7
# Original stencil interior, copied into matching 5x8 frames.
p=[[0,7,7,0,0,7],[7,7,0,7,7,7],[0,7,7,7,0,0]]
for color,rt,ct in [(5,2,2),(1,8,11)]:
 for dr in range(5):
  for dc in range(8):
   if dr in (0,4) or dc in (0,7): g[rt+dr][ct+dc]=color
 for dr in range(3):
  for dc in range(6): g[rt+1+dr][ct+1+dc]=color if p[dr][dc] else 0
print(json.dumps(g,separators=(",",":")))'"
res=terminal(cmd)
print(res.get('output',''))
